CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, icon TEXT NOT NULL DEFAULT '✦');
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', category_id UUID REFERENCES categories(id), price_cents INTEGER NOT NULL CHECK(price_cents >= 0), compare_at_cents INTEGER, rating NUMERIC(2,1) NOT NULL DEFAULT 4.5 CHECK(rating BETWEEN 0 AND 5), review_count INTEGER NOT NULL DEFAULT 0, image_url TEXT NOT NULL DEFAULT '', badge TEXT, is_flash_sale BOOLEAN NOT NULL DEFAULT false, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory (product_id UUID PRIMARY KEY REFERENCES products(id), available INTEGER NOT NULL DEFAULT 0 CHECK(available >= 0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved >= 0), sold INTEGER NOT NULL DEFAULT 0 CHECK(sold >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS addresses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), recipient TEXT NOT NULL, line1 TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, postal_code TEXT NOT NULL, country TEXT NOT NULL DEFAULT 'India', phone TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reservations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), status TEXT NOT NULL DEFAULT 'RESERVED' CHECK(status IN ('RESERVED','PAYMENT_PENDING','CONFIRMED','RELEASED','EXPIRED')), idempotency_key TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS reservations_expiry_idx ON reservations(expires_at) WHERE status IN ('RESERVED','PAYMENT_PENDING');
CREATE TABLE IF NOT EXISTS cart (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL UNIQUE REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cart_items (cart_id UUID NOT NULL REFERENCES cart(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), PRIMARY KEY(cart_id,product_id));
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), reservation_id UUID UNIQUE REFERENCES reservations(id), order_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'CREATED' CHECK(status IN ('CREATED','PAYMENT_PENDING','CONFIRMED','PROCESSING','SHIPPED','OUT_FOR_DELIVERY','DELIVERED','CANCELLED','FAILED')), subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents >= 0), total_cents INTEGER NOT NULL CHECK(total_cents >= 0), address_id UUID REFERENCES addresses(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents >= 0));
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id), reservation_id UUID NOT NULL REFERENCES reservations(id), provider_reference TEXT NOT NULL UNIQUE, amount_cents INTEGER NOT NULL CHECK(amount_cents >= 0), status TEXT NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED','TIMEOUT','REFUNDED')), idempotency_key TEXT NOT NULL UNIQUE, payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shipments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL UNIQUE REFERENCES orders(id), tracking_number TEXT NOT NULL UNIQUE, carrier TEXT NOT NULL DEFAULT 'ShopZen Express', status TEXT NOT NULL DEFAULT 'PROCESSING', eta DATE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), product_id UUID NOT NULL REFERENCES products(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS wishlist (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS idempotency (scope TEXT NOT NULL, user_id UUID NOT NULL REFERENCES users(id), key TEXT NOT NULL, response JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(scope,user_id,key));
CREATE TABLE IF NOT EXISTS outbox_events (id BIGSERIAL PRIMARY KEY, event_type TEXT NOT NULL, aggregate_id UUID NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox_events(available_at,id) WHERE processed_at IS NULL;
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id,active);
CREATE INDEX IF NOT EXISTS orders_user_created_idx ON orders(user_id,created_at DESC);
